// Helper: run a remote command on the Studio Nexis dev box (.215) via ssh2.
// Decrypts server.rootPasswordEnc exactly like lib/crypto-box.ts; never prints it.
// Usage: node _wave12_ssh.mjs '<remote bash command>'
import "dotenv/config";
import { scryptSync, createDecipheriv } from "node:crypto";
import { Client } from "ssh2";
import { PrismaClient } from "@prisma/client";

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";
const EXPECT_IP = "51.79.226.215";

function deriveKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET unset");
  return scryptSync(secret, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  const [ivB64, tagB64, dataB64] = enc.split(":");
  if (!ivB64 || !tagB64 || !dataB64) return null;
  const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
  d.setAuthTag(Buffer.from(tagB64, "base64"));
  return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
}

const cmd = process.argv[2];
if (!cmd) { console.error("no command"); process.exit(2); }

const prisma = new PrismaClient();
const server = await prisma.server.findUnique({
  where: { id: SERVER_ID },
  select: { ipAddress: true, sshPort: true, rootPassword: true, rootPasswordEnc: true, hostname: true },
});
await prisma.$disconnect();
if (!server) { console.error("server not found"); process.exit(3); }

const host = server.ipAddress;
if (host !== EXPECT_IP) { console.error(`REFUSE: server ip ${host} != ${EXPECT_IP}`); process.exit(4); }
const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
if (!password) { console.error("no password"); process.exit(5); }
const port = server.sshPort ?? 22;

const conn = new Client();
conn.on("ready", () => {
  conn.exec(cmd, (err, stream) => {
    if (err) { console.error(String(err)); process.exit(6); }
    stream.on("close", (code) => { conn.end(); process.exit(code ?? 0); });
    stream.on("data", (d) => process.stdout.write(d));
    stream.stderr.on("data", (d) => process.stderr.write(d));
  });
});
conn.on("error", (e) => { console.error("SSH error:", e.message); process.exit(7); });
conn.connect({ host, port, username: "root", password, readyTimeout: 30000 });

